import * as ecs from "@8thwall/ecs";

import { gameData } from "../core/game-data";
import { GameState } from "../core/game-state";
import { GAME_CONFIG } from "../core/constants";


// --------------------------------------------------
// Real-time Game Timer
//
// Uses performance.now()
// instead of world.time.delta
//
// Handles:
// - waiting for truck + collectibles
// - 3 second countdown
// - 60 second gameplay timer
// - game over state
// --------------------------------------------------


let countdownStartTime = 0;

let gameStartTime = 0;



ecs.registerComponent({

  name: "timer-system",


  stateMachine: ({defineState}) => {


    defineState("active")

      .initial()


      .onTick(() => {


        const now =
          performance.now();



        //---------------------------------------
        // Waiting for setup
        //---------------------------------------

        if(

          gameData.state === GameState.SCANNING &&

          gameData.truckPlaced &&

          gameData.collectiblesSpawned

        )
        {


          gameData.score = 0;


          gameData.timeLeft =
            GAME_CONFIG.ROUND_TIME;



          gameData.canDrive = false;


          gameData.gameStarted = false;



          countdownStartTime =
            now;



          gameData.countdownTime =
            GAME_CONFIG.COUNTDOWN_TIME;



          gameData.state =
            GameState.COUNTDOWN;



          console.log(
            "[Timer] COUNTDOWN START"
          );


          return;

        }





        //---------------------------------------
        // Countdown
        //---------------------------------------

        if(
          gameData.state === GameState.COUNTDOWN
        )
        {


          const elapsed =
            (now - countdownStartTime) / 1000;



          gameData.countdownTime =
            Math.max(
              0,
              GAME_CONFIG.COUNTDOWN_TIME - elapsed
            );



          if(gameData.countdownTime <= 0)
          {


            gameStartTime =
              now;



            gameData.state =
              GameState.DRIVING;



            gameData.canDrive =
              true;



            gameData.gameStarted =
              true;



            console.log(
              "[Timer] DRIVING START"
            );

          }



          return;

        }





        //---------------------------------------
        // Active gameplay timer
        //---------------------------------------

        if(
          gameData.state === GameState.DRIVING
        )
        {


          const elapsed =
            (now - gameStartTime) / 1000;



          gameData.timeLeft =
            Math.max(

              0,

              GAME_CONFIG.ROUND_TIME -
              elapsed

            );



          if(gameData.timeLeft <= 0)
          {


            gameData.canDrive =
              false;



            gameData.state =
              GameState.GAMEOVER;



            console.log(
              "[Timer] GAME OVER"
            );


          }


          return;

        }





        //---------------------------------------
        // Game over lock
        //---------------------------------------

        if(
          gameData.state === GameState.GAMEOVER
        )
        {

          gameData.canDrive = false;

        }



      });


  },


});
